import{_ as s,o as a,c as t,ah as i}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Secrétariat","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/secretariat/index.md","filePath":"src/guide/secretariat/index.md"}'),r={name:"guide/secretariat/index.md"};function n(d,e,l,o,u,c){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="secretariat" tabindex="-1">Secrétariat <a class="header-anchor" href="#secretariat" aria-label="Permalink to &quot;Secrétariat&quot;">​</a></h1><p>Le secrétariat est la porte d&#39;entrée des candidatures : c&#39;est vous qui examinez les dossiers déposés par les familles — en ligne via le formulaire public, ou saisis directement par la caisse pour une famille présente sur site — et qui décidez de les valider ou de les refuser. Vous gérez également les demandes de transfert d&#39;un élève déjà inscrit d&#39;un site à un autre, et les changements de classe au sein d&#39;un même site. L&#39;espace <strong>Élèves et admissions</strong> vous donne accès à trois pages :</p><ul><li><strong><a href="/era-guide/guide/secretariat/candidatures.html">Dossiers à traiter</a></strong> — la file d&#39;attente des candidatures reçues, avec les documents joints et la décision d&#39;affectation à une classe.</li><li><strong><a href="/era-guide/guide/secretariat/transferts-sites.html">Mobilité inter-site</a></strong> — les demandes de transfert d&#39;un élève entre deux sites de l&#39;établissement.</li><li><strong><a href="/era-guide/guide/secretariat/changements-de-classe.html">Changements de classe</a></strong> — faire passer un élève dans une autre classe du même site, par exemple après un changement d&#39;orientation.</li></ul><p>Dans un établissement d&#39;enseignement supérieur, l&#39;espace <strong>Supérieur</strong> ajoute <strong><a href="/era-guide/guide/secretariat/releves-attestations.html">Relevés et attestations</a></strong> : les relevés de notes et les attestations de réussite publiés, à imprimer.</p><p>Une fois qu&#39;un dossier est validé, l&#39;élève est inscrit dans une classe et son dossier financier apparaît chez la caisse, qui prend le relais pour les frais et les paiements — voir le <a href="/era-guide/guide/caissier/">guide de la caisse</a>.</p><h2 id="les-pieces-des-dossiers" tabindex="-1">Les pièces des dossiers <a class="header-anchor" href="#les-pieces-des-dossiers" aria-label="Permalink to &quot;Les pièces des dossiers&quot;">​</a></h2><p>Si l&#39;établissement a activé la gestion documentaire, l&#39;espace <strong>Documents</strong> vous permet par défaut de déposer et de valider les pièces des élèves (dossier d&#39;inscription, acte de naissance…), par exemple quand une famille les apporte au guichet. Voir <a href="/era-guide/guide/gestion-documentaire/">Gestion documentaire</a>.</p>',7)])])}const g=s(r,[["render",n]]);export{m as __pageData,g as default};
